package com.nuvio.tv.core.sound

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import android.os.SystemClock
import android.view.KeyEvent
import com.nuvio.tv.R

/**
 * Pop-zen UI sound design (generated by scripts/generate_ui_sounds_v2.js). One tiny [SoundPool] with five
 * short samples, driven from the activity's key dispatch so every screen gets sound without
 * touching individual components. Muted automatically during playback.
 */
object UiSounds {
    enum class Cue(val rawRes: Int, val volume: Float, val minGapMs: Long) {
        MOVE(R.raw.ui_move, 0.48f, 55L),
        TAB(R.raw.ui_tab, 0.6f, 80L),
        SELECT(R.raw.ui_select, 0.7f, 120L),
        BACK(R.raw.ui_back, 0.56f, 150L),
    }

    private const val PREFS = "nawflix_audio"
    private const val KEY_ENABLED = "ui_sounds"
    private const val INTRO_VOLUME = 0.72f

    @Volatile
    var enabled: Boolean = true
        private set

    /** Set by the scaffold: true while the video player owns the screen. */
    @Volatile
    var suspended: Boolean = false

    /** Set by the scaffold: true while focus is in the top navigation bar. */
    @Volatile
    var inTopBar: Boolean = false

    private var pool: SoundPool? = null
    private val ids = HashMap<Cue, Int>()
    private val lastPlayed = HashMap<Cue, Long>()
    private var introId = 0
    private val loaded = HashSet<Int>()
    private var introRequested = false

    fun init(context: Context) {
        if (pool != null) return
        val app = context.applicationContext
        enabled = app.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getBoolean(KEY_ENABLED, true)
        val sp = SoundPool.Builder()
            .setMaxStreams(3)
            .setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
                    .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                    .build()
            )
            .build()
        sp.setOnLoadCompleteListener { _, sampleId, status ->
            if (status != 0) return@setOnLoadCompleteListener
            val playIntroNow = synchronized(this) {
                loaded += sampleId
                sampleId == introId && introRequested
            }
            if (playIntroNow) sp.play(sampleId, INTRO_VOLUME, INTRO_VOLUME, 1, 0, 1f)
        }
        Cue.values().forEach { ids[it] = sp.load(app, it.rawRes, 1) }
        introId = sp.load(app, R.raw.nawflix_intro_chime, 1)
        pool = sp
    }

    fun setEnabled(context: Context, value: Boolean) {
        enabled = value
        context.applicationContext.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
            .edit().putBoolean(KEY_ENABLED, value).apply()
    }

    fun play(cue: Cue) {
        if (!enabled || suspended) return
        val sp = pool ?: return
        val id = ids[cue] ?: return
        val now = SystemClock.uptimeMillis()
        if (now - (lastPlayed[cue] ?: 0L) < cue.minGapMs) return
        lastPlayed[cue] = now
        synchronized(this) { if (id !in loaded) return }
        sp.play(id, cue.volume, cue.volume, 1, 0, 1f)
    }

    /** Plays the intro now, or as soon as the sample has finished loading. */
    fun playIntro() {
        if (!enabled) return
        val sp = pool ?: return
        val ready = synchronized(this) {
            introRequested = true
            introId in loaded
        }
        if (ready) sp.play(introId, INTRO_VOLUME, INTRO_VOLUME, 1, 0, 1f)
    }

    /** Maps a remote key press to a cue. Called from Activity.dispatchKeyEvent. */
    fun onKey(event: KeyEvent) {
        if (event.action != KeyEvent.ACTION_DOWN) return
        when (event.keyCode) {
            KeyEvent.KEYCODE_DPAD_LEFT, KeyEvent.KEYCODE_DPAD_RIGHT ->
                play(if (inTopBar) Cue.TAB else Cue.MOVE)
            KeyEvent.KEYCODE_DPAD_UP, KeyEvent.KEYCODE_DPAD_DOWN -> play(Cue.MOVE)
            KeyEvent.KEYCODE_DPAD_CENTER, KeyEvent.KEYCODE_ENTER, KeyEvent.KEYCODE_NUMPAD_ENTER ->
                if (event.repeatCount == 0) play(Cue.SELECT)
            KeyEvent.KEYCODE_BACK -> if (event.repeatCount == 0) play(Cue.BACK)
        }
    }
}
